select *, row_number() over (partition by store_id, product_id order by quantity asc, id asc) row_seq, first_value(quantity, true) over w_part first_known_quantity, avg(quantity) over (partition by store_id, product_id order by quantity asc, id asc rows between 5 preceding and current row) quantity_avg_5 from inventory window w_part as (partition by store_id order by quantity asc, id asc rows between unbounded preceding and current row);
